        <el-card shadow="never" class="panel-card">
          <template #header><div class="panel-heading"><div><span class="step">02</span><strong>{{ t("Survey route & array") }}</strong></div><el-button size="small" @click="preview" :loading="previewing" :disabled="running">{{ t("Preview geometry") }}</el-button></div></template>
          <div class="chart-meta"><span>{{ t(activePlan ? `${activePlan.label} · ${activePlan.angle_deg}°` : 'Preview: first shape at the smallest radius') }}</span><span v-if="activePlan">{{ t(fmt(activePlan.duration_h)) }} {{ t("h ·") }} {{ t(activePlan.observations_count) }} {{ t("observations") }}</span></div>
