          <p class="field-note">{{ t("Complete routes include their transfer travel. Dashed segments are transfers, with sampling off by default. Beacons respond in sequence; propagation time limits the sampling interval.") }}</p>
        </el-card>
        <template v-if="result"><el-alert v-if="settingsChanged" :title="t(`Inputs changed. These results belong to the saved run with ${result.n_beacons} beacons. Run the simulation to update them.`)" type="info" :closable="false" show-icon/>
          <el-card v-if="result.budget_results?.length" shadow="never" class="panel-card budget-panel">
            <template #header><div class="panel-heading"><strong>{{ t("Time budget comparison") }}</strong><el-select v-model="activeBudgetIndex" :aria-label="t(&quot;Select result time budget&quot;)" @change="selectBudget"><el-option v-for="(b,i) in result.budget_results" :key="i" :label="t(`${fmt(b.budget_h,3)} h`)" :value="i"/></el-select></div></template>
            <p class="field-note">{{ t("Ten logarithmically spaced time caps, including both limits. Each row selects complete routes from the same simulation run. Select a budget to inspect its plans.") }}</p>
            <el-table :data="result.budget_results" size="small" stripe @row-click="budgetRowClick" highlight-current-row>
              <el-table-column :label="t(&quot;Budget / h&quot;)" width="105"><template #default="{row}">{{ t(fmt(row.budget_h,3)) }}</template></el-table-column>
              <el-table-column prop="n_eligible" :label="t(&quot;Eligible&quot;)" width="85"/>
              <el-table-column :label="t(&quot;Minimum-risk route&quot;)" min-width="150"><template #default="{row}">{{ t(planFor(row.plan_a)?.label ?? 'No eligible route') }}</template></el-table-column>
              <el-table-column :label="t(&quot;Actual duration / h&quot;)" min-width="130"><template #default="{row}">{{ t(fmt(planFor(row.plan_a)?.duration_h,3)) }}</template></el-table-column>
              <el-table-column :label="t(&quot;Design risk / m²&quot;)" min-width="125"><template #default="{row}">{{ t(fmt(planFor(row.plan_a)?.[result.criterion+'_m2'],4)) }}</template></el-table-column>
