          <div class="run-summary"><div v-for="(label,key) in summaryLabels" :key="key"><small>{{ t(key==='n_valid'&&result.field_validation?'Valid designs':label) }}</small><strong>{{ t(displaySummary[key]) }}</strong></div></div>
          <el-alert v-if="!currentPlans.plan_a" :title="t(selectedBudget?.message ?? result.message)" type="warning" :closable="false" show-icon/>
          <div v-else class="plan-grid"><button v-for="(label,key) in planLabels" :key="key" class="plan-choice" :class="{selected:activeKey===key}" @click="selectPlan(key)"><span class="plan-caption">{{ t(label) }}</span><strong>{{ t(currentPlans[key]?.label) }}</strong><span>{{ t(fmt(currentPlans[key]?.duration_h)) }} {{ t("h ·") }} {{ t(fmt(currentPlans[key]?.length/1000)) }} {{ t("km") }}</span><span>{{ t("Design risk") }} {{ t(fmt(currentPlans[key]?.[result.criterion+'_m2'],4)) }} {{ t("m²") }}</span><small>{{ t("3D error in this run") }} {{ t(fmt(currentPlans[key]?.rmse_3d_m,3)) }} {{ t("m") }}</small></button></div>
          <el-card v-if="displaySummary.n_valid" shadow="never" class="panel-card"><OptimizationScatterChart :all-results="result.all_results.filter((r:any)=>r.valid && r.duration_h <= (selectedBudget?.budget_h ?? Infinity))" :criterion="result.criterion"/></el-card>
