            <div class="metric-strip"><span>{{ t("C1") }} <b>{{ t(fmt(activePlan.c1_m2,4)) }}</b> {{ t("m²") }}</span><span>{{ t("C2") }} <b>{{ t(fmt(activePlan.c2_m2,4)) }}</b> {{ t("m²") }}</span><span>{{ t("C3") }} <b>{{ t(fmt(activePlan.c3_m2,4)) }}</b> {{ t("m²") }}</span><span>{{ t("Slot") }} <b>{{ t(fmt(activePlan.slot_s,1)) }}</b> {{ t("s") }}</span><span>{{ t("Max. geometric GDOP") }} <b>{{ t(fmt(activePlan.gdop,3)) }}</b></span></div>
          </el-card>
          <el-card shadow="never" class="panel-card"><template #header><div class="panel-heading"><strong>{{ t("All candidate routes") }}</strong><el-button size="small" @click="downloadRun">{{ t("Export run JSON") }}</el-button></div></template><el-table :data="result.all_results" max-height="330" size="small" stripe><el-table-column :label="t(&quot;Shape&quot;)" min-width="100"><template #default="{row}">{{ t(row.label) }}</template></el-table-column><el-table-column :label="t(&quot;Radial extent / m&quot;)" width="100"><template #default="{row}">{{ t(fmt(row.size,0)) }}</template></el-table-column><el-table-column :label="t(&quot;Scale parameter / m&quot;)" min-width="150"><template #default="{row}">{{ t(row.scale_parameter==='side_length_m'?'Side':'Radius') }} {{ t(fmt(row.scale_value_m,0)) }}</template></el-table-column><el-table-column :label="t(&quot;Scale source&quot;)" min-width="140"><template #default="{row}">{{ t(row.search_source) }}</template></el-table-column><el-table-column prop="angle_deg" :label="t(&quot;Angle / °&quot;)" width="85"/><el-table-column :label="t(&quot;Duration / h&quot;)" width="90"><template #default="{row}">{{ t(fmt(row.duration_h)) }}</template></el-table-column><el-table-column :label="t(&quot;Status / reason&quot;)" min-width="240"><template #default="{row}"><span v-if="row.valid">{{ t("Valid ·") }} {{ t(row.observations_count) }} {{ t("observations") }}<span v-if="row.validation_status"> · {{ t(row.validation_status==='success'?'Validation succeeded':row.validation_status==='failed'?'Validation failed':'Design score only') }}</span><span v-if="row.gdop>result.config.gdop_threshold"> {{ t("· GDOP exceeds limit") }}</span></span><span v-else class="failure-note">{{ t(row.reason) }}</span></template></el-table-column></el-table></el-card>
