          <el-collapse class="model-notes"><el-collapse-item :title="t(&quot;Model assumptions &amp; interpretation&quot;)" name="model"><p v-for="note in result.model_notes" :key="note">{{ t(note) }}</p></el-collapse-item></el-collapse>
        </template>
