          <el-form-item :label="t(&quot;Route family&quot;)"><el-select v-model="form.mode" :aria-label="t(&quot;Route family&quot;)"><el-option :label="t(&quot;All survey families (6)&quot;)" value="all"/><el-option v-for="(label,key) in families" :key="key" :label="t(label)" :value="key"/></el-select></el-form-item><p class="field-note family-note">{{ t(familyReason) }}</p>
          <div class="input-pair"><el-form-item :label="t(&quot;Min. radius / depth&quot;)"><el-input-number v-model="form.minRatio" :min="0.1" :max="100" :step="0.1" :precision="2" controls-position="right"/></el-form-item><el-form-item :label="t(&quot;Max. radius / depth&quot;)"><el-input-number v-model="form.maxRatio" :min="form.minRatio" :max="100" :step="0.5" :precision="2" controls-position="right"/></el-form-item></div>
          <div class="input-pair"><el-form-item :label="t(&quot;Seed scales&quot;)"><el-input-number v-model="form.scaleCount" :min="2" :max="12" controls-position="right"/></el-form-item><el-form-item :label="t(&quot;180° divisions&quot;)"><el-input-number v-model="form.rotationDivisions" :aria-label="t(&quot;180-degree divisions&quot;)" :min="1" :max="180" :step="1" :precision="0" step-strictly controls-position="right"/></el-form-item></div>
          <p class="field-note">{{ t("Angles:") }} {{ t(rotationAngles.slice(0,12).map(a=>`${fmt(a,2).replace(/\.?0+$/,'')}°`).join(' · ')) }}{{ t(rotationAngles.length>12?' · …':'') }}{{ t(". Divide 180° into equal steps; start at 0° and exclude 180°. For circles, this sets the starting phase.") }}</p>
          <p class="field-note">{{ t("Current radial extent:") }} {{ t(fmt(meanDepth*form.minRatio,0)) }}–{{ t(fmt(meanDepth*form.maxRatio,0)) }} {{ t("m. Square side length is √2 × radial extent. Budget-boundary scales and local refinements stay inside these limits.") }}</p>
          <el-form-item :label="t(&quot;Scale refinement&quot;)"><el-select v-model="form.refinementRounds"><el-option :label="t(&quot;Seeds and budget boundaries only&quot;)" :value="0"/><el-option :label="t(&quot;One refinement round&quot;)" :value="1"/><el-option :label="t(&quot;Two refinement rounds&quot;)" :value="2"/></el-select></el-form-item>
          <p class="field-note">{{ t("Refinement tests extra sizes near promising C1/C2/C3 candidates for each shape and angle within the time caps. On the logarithmic grid, 4 and 9 km give a new 6 km size. One round adds once; two rounds repeat. Bounds and complete-route rules stay fixed; more rounds take longer.") }}</p>
          <el-form-item :label="t('Ship speed')"><el-radio-group v-model="speedUnit" :aria-label="t('Speed unit')"><el-radio-button value="kn">{{ t('Knots (kn)') }}</el-radio-button><el-radio-button value="mps">{{ t('Metres per second (m/s)') }}</el-radio-button></el-radio-group><el-input-number v-model="speedValue" :aria-label="t('Ship speed')" :min="speedUnit==='kn'?.5:.5*.514444" :max="speedUnit==='kn'?20:20*.514444" :step="speedUnit==='kn'?.5:.1" :precision="6" controls-position="right"/></el-form-item>
          <p class="field-note">{{ fmt(form.shipSpeedKn,4) }} {{ t('kn') }} ≈ {{ fmt(form.shipSpeedKn*.514444,4) }} m/s. {{ t('Changing units keeps the same physical speed.') }}</p>
          <div class="input-pair"><el-form-item :label="t(&quot;Min. budget (h)&quot;)"><el-input-number v-model="form.budgetMin" :aria-label="t(&quot;Minimum time budget in hours&quot;)" :min="0.1" :max="48" :step="0.1" :precision="3" controls-position="right"/></el-form-item><el-form-item :label="t(&quot;Max. budget (h)&quot;)"><el-input-number v-model="form.budgetMax" :aria-label="t(&quot;Maximum time budget in hours&quot;)" :min="0.1" :max="48" :step="0.1" :precision="3" controls-position="right"/></el-form-item></div>
          <p class="field-note" v-if="budgetValues.length">{{ t("10 time caps (h):") }} {{ t(budgetValues.map(v=>fmt(v,3)).join(' · ')) }}</p>
          <p class="failure-note field-note" v-else>{{ t("Enter a minimum budget smaller than the maximum budget.") }}</p>
          <el-form-item :label="t(&quot;Design criterion&quot;)"><el-select v-model="form.criterion"><el-option :label="t(&quot;Worst-case coordinate risk (C3)&quot;)" value="c3"/><el-option :label="t(&quot;Average coordinate risk (C2)&quot;)" value="c2"/><el-option :label="t(&quot;Nominal coordinate variance (C1)&quot;)" value="c1"/></el-select></el-form-item><el-form-item :label="t(&quot;GDOP limit&quot;)"><el-input-number v-model="form.gdop" :min="0.1" :max="100" :step="0.1" controls-position="right"/></el-form-item>
          <p class="field-note">{{ t("C1: nominal variance. C2: average environmental risk. C3: worst direction in the declared ellipsoid. Choose according to the risk assumptions; neither criterion guarantees the best validation result.") }}</p>
          <h3>{{ t("Observations & coverage") }}</h3>
          <el-form-item :label="t(&quot;Sample straight transfer&quot;)"><el-switch v-model="form.collectTransfer"/></el-form-item><p class="field-note">{{ t("Off by default. Transfer travel always counts in sailing time.") }}</p>
          <el-form-item :label="t(&quot;Usable slant range (km)&quot;)"><el-input-number v-model="form.maxRange" :min="0.1" :max="200" :step="1" controls-position="right"/></el-form-item><p class="field-note">{{ t("Set the usable slant range for your equipment. Only observations to the out-of-range beacon are excluded.") }}</p>
          <el-form-item :label="t(&quot;Sampling units&quot;)"><el-radio-group v-model="form.sampleMode"><el-radio-button value="hz">{{ t("Hz") }}</el-radio-button><el-radio-button value="sec">{{ t("Seconds / ping") }}</el-radio-button></el-radio-group></el-form-item>
          <el-form-item v-if="form.sampleMode==='hz'" :label="t(&quot;Requested rate (Hz)&quot;)"><el-input-number v-model="form.sampleHz" :min="0.001" :max="10" :step="0.01" :precision="3" controls-position="right"/></el-form-item><el-form-item v-else :label="t(&quot;Requested interval (s)&quot;)"><el-input-number v-model="form.interval" :min="1" :max="600" :step="5" controls-position="right"/></el-form-item>
          <el-form-item :label="t(&quot;Acoustic time noise σ (s)&quot;)"><el-input-number v-model="form.noise" :min="0" :max="0.1" :step="0.0001" :precision="6" controls-position="right"/></el-form-item><el-form-item :label="t(&quot;Dropout probability&quot;)"><el-input-number v-model="form.dropout" :min="0" :max="0.95" :step="0.05" :precision="2" controls-position="right"/></el-form-item>
          <el-collapse><el-collapse-item :title="t(&quot;Vessel &amp; sound field&quot;)" name="physical"><p class="field-note">{{ t("Lever arm is the transducer position relative to the GNSS antenna, expressed in the vessel local frame: right, forward, up. A downward offset is negative; attitude rotates this vector into ENU.") }}</p><el-form-item v-for="(label,i) in ['Right','Forward','Up']" :key="label" :label="t(`Lever arm ${label} (m)`)"><el-input-number v-model="form.lever[i]" :step="0.1" :precision="3" controls-position="right"/></el-form-item><el-form-item :label="t(&quot;GNSS σ (m)&quot;)"><el-input-number v-model="form.gnss" :min="0" :max="10" :step="0.01" :precision="3" controls-position="right"/></el-form-item><el-form-item :label="t(&quot;East gradient (m/s/km)&quot;)"><el-input-number :disabled="fieldMode==='profiles'" v-model="form.ge" :step="0.01" :precision="3" controls-position="right"/></el-form-item><el-form-item :label="t(&quot;North gradient (m/s/km)&quot;)"><el-input-number :disabled="fieldMode==='profiles'" v-model="form.gn" :step="0.01" :precision="3" controls-position="right"/></el-form-item><el-form-item :label="t(&quot;Temporal sound-speed σ (m/s)&quot;)"><el-input-number :disabled="fieldMode==='profiles'" v-model="form.sa" :min="0" :max="10" :step="0.1" controls-position="right"/></el-form-item><el-form-item :label="t(&quot;Correlation time (s)&quot;)"><el-input-number :disabled="fieldMode==='profiles'" v-model="form.tau" :min="1" :max="86400" :step="300" controls-position="right"/></el-form-item><p class="field-note">{{ t(fieldMode==='profiles'?"Profile mode uses the uploaded training ensemble. Analytic OU and gradient controls are inactive.":"A shared temporal field and horizontal gradients are integrated along curved rays. Joint fitting estimates static sound speed and delay terms.") }}</p></el-collapse-item></el-collapse>
          <el-form-item :label="t(&quot;Random seed&quot;)"><el-input-number v-model="form.seed" :min="0" :max="4294967295" controls-position="right"/></el-form-item>
        </el-form>
        <div class="run-controls"><span>{{ t(candidateCount) }} {{ t("seed candidates · budget scales and refinements added") }}</span><el-button type="primary" size="large" :loading="running" @click="run">{{ t(running?'Solving array':'Run simulation') }}</el-button><el-progress v-if="running" :percentage="progress" :stroke-width="6"/><p v-if="running" role="status">{{ t(statusMessage) }}</p><p v-if="runError" class="failure-note" role="alert">{{ t(runError) }}</p></div>
      </el-card></aside>
    </div>
  </section>
</template>

<script setup lang="ts">
import { t, locale, setLocalizedOption } from "../i18n"
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {apiClient} from '../api'
import TrajectoryChart from './TrajectoryChart.vue'
import OptimizationScatterChart from './OptimizationScatterChart.vue'
import ResultExportPanel from './ResultExportPanel.vue'
import SoundFieldInput from './SoundFieldInput.vue'
import ProfileValidationResult from './ProfileValidationResult.vue'
const fieldMode=ref('munk'),fieldSettings=ref<any>({background_csv:'',history_csv:'',training_end:'2020-06-30',validation_start:'2020-07-15',validation_date:'2020-07-15',validation_scope:'single',amplitude:1}),inspectedPlanId=ref('')
const families:Record<string,string>={circle:'Circle',figure_eight:'Figure eight',clover:'Clover',square:'Square',rose:'Four-petal rose',circle_cross:'Circle + cross'}
const reasons:Record<string,string>={circle:'Peripheral azimuth coverage. Radius is the maximum radial extent from the array centre.',figure_eight:'Two lobes cross at one point without retracing either lobe.',clover:'Three lobes connect the centre and perimeter from multiple directions.',square:'Four straight sides test perimeter coverage and corner directions.',circle_cross:'One circle, two perpendicular diameters and a straight transfer. Transfer time is included; sampling there is off by default.',square_cross:'A square perimeter with perpendicular crossings to compare coverage and extra travel.',rose:'A four-petal shape comparator, not a reproduction of a published optimisation algorithm.',asterisk:'Legacy star route: eight radial out-and-back legs.'}
const defaults=()=>[[3000,3000,-3150],[-3000,3000,-3180],[-3000,-3000,-3220],[3000,-3000,-3250]]
const form=reactive({arrayPoints:defaults(),lever:[-1.269,1.555,-23.73],gnss:.05,collectTransfer:false,mode:'all',shipSpeedKn:3,sampleMode:'sec',sampleHz:1,interval:20,noise:.0001,gdop:2.5,ge:0,gn:.04,sa:.3,tau:1800,maxRange:10,budgetMin:5,budgetMax:25,dropout:0,seed:20261002,minRatio:.5,maxRatio:10,scaleCount:8,refinementRounds:1,rotationDivisions:4,criterion:'c3'})
const runTaskId=ref(''),speedUnit=ref<'kn'|'mps'>('kn')
const speedValue=computed({get:()=>speedUnit.value==='kn'?form.shipSpeedKn:form.shipSpeedKn*.514444,set:(value:number)=>{form.shipSpeedKn=speedUnit.value==='kn'?value:value/.514444}})
const beaconCount=ref(4),running=ref(false),previewing=ref(false),progress=ref(0),statusMessage=ref(''),runError=ref('')
const result=ref<any>(null),activeKey=ref('plan_a'),trajectory=ref<Array<{x:number,y:number}>>([]),runBeacons=ref<number[][]>([])
const planLabels:Record<string,string>={plan_a:'A · Minimum design risk',plan_b:'B · Shortest lower-risk route',plan_c:'C · Risk–duration balance'}
const summaryLabels:Record<string,string>={n_total:'Candidates',n_valid:'Valid solutions',n_eligible:'Eligible routes',rng_seed:'Run seed'}
const settingsChanged=computed(()=>result.value && JSON.stringify(payload())!==JSON.stringify(result.value.config))
const activeBudgetIndex=ref(9)
const budgetValues=computed(()=>Number.isFinite(form.budgetMin)&&Number.isFinite(form.budgetMax)&&form.budgetMin>0&&form.budgetMax>form.budgetMin?Array.from({length:10},(_,i)=>i===0?form.budgetMin:i===9?form.budgetMax:Math.exp(Math.log(form.budgetMin)+(Math.log(form.budgetMax)-Math.log(form.budgetMin))*i/9)):[])
const selectedBudget=computed(()=>result.value?.budget_results?.[activeBudgetIndex.value]??null)
function planFor(id:string|null){return id?result.value?.plans_by_id?.[id]??null:null}
const currentPlans=computed(()=>selectedBudget.value?Object.fromEntries(Object.keys(planLabels).map(k=>[k,planFor(selectedBudget.value[k])])):result.value??{})
const displaySummary=computed(()=>({...result.value,n_valid:selectedBudget.value?.n_valid??result.value?.n_valid,n_eligible:selectedBudget.value?.n_eligible??result.value?.n_eligible}))
const activePlan=computed(()=>inspectedPlanId.value?planFor(inspectedPlanId.value):currentPlans.value[activeKey.value]??null)
const displayBeacons=computed(()=>result.value?runBeacons.value:form.arrayPoints)
const familyReason=computed(()=>reasons[form.mode]??'Compare six complete survey families. Circle plus cross includes a straight transfer; no route is padded with extra laps.')
const meanDepth=computed(()=>-form.arrayPoints.reduce((s,b)=>s+b[2],0)/form.arrayPoints.length)
const rotationAngles=computed(()=>Number.isInteger(form.rotationDivisions)&&form.rotationDivisions>=1&&form.rotationDivisions<=180?Array.from({length:form.rotationDivisions},(_,i)=>180*i/form.rotationDivisions):[])
const candidateCount=computed(()=>(form.mode==='all'?6:1)*form.scaleCount*rotationAngles.value.length)
let pollTimer:ReturnType<typeof setTimeout>|undefined;let generation=0
function resizeBeacons(value:number|undefined){if(running.value)return;const n=Math.min(64,Math.max(1,value??1));while(form.arrayPoints.length<n){const b=form.arrayPoints.at(-1)??[0,0,-1500];form.arrayPoints.push([b[0]+300,b[1]+300,b[2]])}form.arrayPoints.splice(n);beaconCount.value=n}
function removeBeacon(i:number){form.arrayPoints.splice(i,1);beaconCount.value=form.arrayPoints.length}
function resetBeacons(){form.arrayPoints=defaults();beaconCount.value=4}
function fmt(n:any,d=2){return typeof n==='number'&&Number.isFinite(n)?n.toFixed(d):'—'}
function payload(){return {sound_field_mode:fieldMode.value,...(fieldMode.value==='profiles'?{sound_field:fieldSettings.value}:{}),array_points:form.arrayPoints.map(b=>[...b]),lever_arm:[...form.lever],gnss_noise_std:form.gnss,use_ray_tracing:true,modes:form.mode==='all'?Object.keys(families):[form.mode],ship_speed_kn:form.shipSpeedKn,sample_freq_hz:form.sampleMode==='hz'?form.sampleHz:1/form.interval,noise:form.noise,gdop_threshold:form.gdop,sv_grad_e:fieldMode.value==='profiles'?0:form.ge/1000,sv_grad_n:fieldMode.value==='profiles'?0:form.gn/1000,temporal_sigma_mps:fieldMode.value==='profiles'?0:form.sa,correlation_time_s:form.tau,max_range_km:form.maxRange,time_budget_min_h:form.budgetMin,time_budget_max_h:form.budgetMax,dropout_probability:form.dropout,rng_seed:form.seed,criterion:form.criterion,collect_transfer:form.collectTransfer,rotation_divisions:form.rotationDivisions,scale_min_ratio:form.minRatio,scale_max_ratio:form.maxRatio,scale_count:form.scaleCount,refinement_rounds:form.refinementRounds}}
function errorText(e:any){const d=e?.response?.data?.detail;return typeof d==='string'?d:(e?.message??'Connection failed')}
async function preview(){previewing.value=true;try{const body=payload();const key=JSON.stringify(body);const r=await apiClient.post('/api/simulation/preview',body);if(key!==JSON.stringify(payload()))return;trajectory.value=r.data.trajectory;result.value=null}catch(e){localizedMessage.error(errorText(e))}finally{previewing.value=false}}
function inspectPlan(id:string){inspectedPlanId.value=id;trajectory.value=planFor(id)?.trajectory??[]}
function selectPlan(key:string){inspectedPlanId.value='';activeKey.value=key;trajectory.value=currentPlans.value[key]?.trajectory??[]}
function selectBudget(){selectPlan('plan_a')}
function budgetRowClick(row:any){activeBudgetIndex.value=result.value.budget_results.indexOf(row);selectBudget()}
async function run(){
  if(!rotationAngles.value.length){runError.value='Enter an integer from 1 to 180 for 180-degree divisions.';return}
  if(!Number.isFinite(form.minRatio)||!Number.isFinite(form.maxRatio)||form.minRatio<=0||form.maxRatio<form.minRatio){runError.value='Enter ordered positive scale limits.';return}
  if(!budgetValues.value.length){runError.value='Enter a minimum budget smaller than the maximum budget.';return}
  const token=++generation;clearTimeout(pollTimer);running.value=true;progress.value=0;runError.value='';statusMessage.value='Submitting simulation';result.value=null;trajectory.value=[]
  try{const body=payload();runBeacons.value=body.array_points;const {data}=await apiClient.post('/api/calculate',body);if(!data.task_id)throw new Error('The server did not return a task ID');runTaskId.value=data.task_id;let failures=0
    const poll=async()=>{if(token!==generation)return;try{const {data:r}=await apiClient.get(`/api/progress/${data.task_id}`);failures=0;progress.value=r.progress??0;statusMessage.value=r.message??'Computing';if(r.status==='completed'){result.value=r.result;activeBudgetIndex.value=(r.result.budget_results?.length??1)-1;running.value=false;selectPlan('plan_a');if(r.result.plan_a)localizedMessage.success('Joint simulation complete');return}if(r.status==='failed')throw new Error(r.error??'Simulation failed')}
    catch(e:any){if(!e?.response&&!e?.request){runError.value=errorText(e);running.value=false;return}failures++;statusMessage.value=`Connection lost. Retrying ${failures}/5`;if(failures>=5){runError.value=errorText(e);running.value=false;return}}pollTimer=setTimeout(poll,800)};await poll()
  }catch(e){runError.value=errorText(e);running.value=false}
}
function save(content:string,name:string,type:string){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadRun(){save(JSON.stringify(result.value,null,2),'seaarray-survey-result.json','application/json')}
function downloadObservations(){const rows=activePlan.value?.observations??[];if(!rows.length)return;const columns=Object.keys(rows[0]);save('\ufeff'+[columns.join(','),...rows.map((r:any)=>columns.map(k=>r[k]).join(','))].join('\r\n'),'seaarray-one-way-observations.csv','text/csv;charset=utf-8')}
watch(()=>JSON.stringify(payload()),()=>{if(!result.value&&!running.value)trajectory.value=[]})
onBeforeUnmount(()=>{generation++;clearTimeout(pollTimer)})
const localizedMessage={success:(v:any)=>ElMessage.success(t(v)),error:(v:any)=>ElMessage.error(t(v)),warning:(v:any)=>ElMessage.warning(t(v))}
</script>

